#---------------------------V3---------------------------------------

class HoldingV3(BaseModel):
    """
    Represents an individual holding in a user's portfolio.

    Attributes:
        refId (int): Reference ID of the holding.
        nubraName (str): Internal name used by Nubra (aliased from `zanskarName`).
        displayName (str): Display name for UI.
        derivativeType (str): Type of derivative instrument, if applicable.
        strikePrice (Optional[int]): Strike price in paise, converted to float.
        lotSize (Optional[int]): Lot size for derivative instruments.
        exchange (str): Exchange code (e.g., NSE, BSE, MCX).
        asset (str): Underlying asset type.
        symbol (str): Trading symbol.
        quantity (int): Number of units held (aliased from `qty`).
        pledgedQty (Optional[int]): Quantity pledged as collateral.
        t1Qty (Optional[int]): Quantity in T+1 settlement.
        avgPrice (Optional[int]): Average buy price (converted from paise).
        prevClose (Optional[int]): Previous closing price.
        lastTradedPrice (Optional[int]): Last traded price (aliased from `ltp`).
        lastTradedPriceChange (Optional[int]): LTP change (aliased from `ltpChange`).
        investedValue (Optional[int]): Total invested value.
        currentValue (Optional[int]): Current market value.
        netPnl (Optional[int]): Net profit or loss.
        netPnlChg (Optional[float]): Change in net PnL.
        dayPnl (Optional[int]): Daily profit or loss.
        haircut (Optional[float]): Haircut percentage for pledging.
        marginBenefit (Optional[int]): Margin benefit obtained from holding.
        availableToPledge (Optional[int]): Quantity available for pledging.
    """
    refId: int
    nubraName: str= Field(alias= "zanskarName")
    displayName: str
    derivativeType: str
    strikePrice: Optional[int]= None
    lotSize: Optional[int]= None
    exchange: str
    asset: str
    symbol: str
    isin: Optional[str] = None
    assetType: Optional[str] = None
    tickSize: Optional[int] = None
    quantity: int= Field(default= None, alias= "qty")
    cuspaQty: Optional[int] = None
    pledgedQty: Optional[int]= None
    t1Qty: Optional[int]= None
    avgPrice: Optional[int]= None
    prevClose: Optional[int]= None
    lastTradedPrice: Optional[int]= Field(default= None, alias= "ltp")
    lastTradedPriceChange: Optional[float]= Field(default= None, alias= "ltpChange")
    investedValue: Optional[int]= None
    currentValue: Optional[int]= None
    netPnl: Optional[int]= None
    netPnlChg: Optional[float] = None
    dayPnl: Optional[int] = None
    dayPnlChg: Optional[float] = None
    haircut: Optional[float]= None
    marginBenefit: Optional[int] = None
    availableToPledge: Optional[int]= None
    availableToUnpledge: Optional[int] = None
    isPledgeable: Optional[bool] = None
    supportedExchanges: Optional[Dict[str, int]] = None

    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        ser_json_exclude_none= True,
        ser_dict_exclude_none= True
    )

