class PositionStructV3(BaseModel):
    """
    Represents an individual open or closed position.

    Attributes:
        refId (Optional[int]): Unique reference ID.
        nubraName (str): Internal name (aliased from `zanskarName`).
        displayName (Optional[str]): Display name for UI.
        derivativeType (Optional[str]): Type of derivative instrument.
        strikePrice (Optional[int]): Strike price (in paise).
        lotSize (Optional[int]): Lot size for the instrument.
        exchange (str): Exchange where instrument is traded.
        asset (str): Asset class.
        symbol (str): Trading symbol.
        orderSide (Optional[str]): Order side (BUY/SELL).
        lastTradedPrice (Optional[float]): LTP (aliased from `ltp`).
        avgPrice (Optional[float]): Average price.
        avgBuyPrice (Optional[float]): Average buy price.
        avgSellPrice (Optional[float]): Average sell price.
        pnl (Optional[float]): Current profit/loss.
        pnlChg (Optional[float]): Change in PnL.
    """
    refId: Optional[int]
    nubraName: str= Field(alias= "zanskarName")
    displayName: Optional[str] = None
    derivativeType: Optional[str] = None
    strikePrice: Optional[int]= None
    lotSize: Optional[int]= None
    exchange: str
    asset: str
    symbol: str
    assetType: Optional[str] = None
    tickSize: Optional[int] = None
    deliveryType: Optional[str] = None
    orderSide: Optional[str]= None
    status: Optional[str] = None
    buyQuantity: Optional[int] = Field(default= None, alias= "buyQty")
    sellQuantity: Optional[int] = Field(default= None, alias= "sellQty")
    netQuantity: Optional[int] = Field(default= None, alias= "netQty")
    lastTradedPrice: Optional[int] = Field(default=None, alias= "ltp")
    avgBuyPrice: Optional[int]= None
    avgSellPrice: Optional[int]= None
    pnl: Optional[int]= None
    pnlChg: Optional[float]= None
    pnlToday: Optional[int] = None
    pnlChgToday: Optional[float] = None
    positionId: Optional[str] = None
    avgPrice: Optional[int] = None
    orders: Optional[List[PositionOrderInfoV3]] = Field(default_factory=list)

    @field_validator("orderSide", mode="before")
    @classmethod
    def _normalize_order_side(cls, value: Any) -> Any:
        # Non-sentinel users send "ORDER_SIDE_BUY"/"ORDER_SIDE_SELL"; normalize to the short form.
        if value is None:
            return value
        return str(value).removeprefix("ORDER_SIDE_")

    @field_validator("deliveryType", mode="before")
    @classmethod
    def _normalize_delivery_type(cls, value: Any) -> Any:
        # Non-sentinel users send "ORDER_DELIVERY_TYPE_IDAY"/"ORDER_DELIVERY_TYPE_CNC"; normalize to the short form.
        if value is None:
            return value
        return str(value).removeprefix("ORDER_DELIVERY_TYPE_")

    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        ser_json_exclude_none= True,
        ser_dict_exclude_none= True
    )

