# ── Tag / untag / move orders — POST /sentinel/strategy-portfolio/orders ──────

class StratOrderUpdate(BaseModel):
    """
    A single order tag mutation for POST /sentinel/strategy-portfolio/orders.

    The change is expressed as a delta: ``oldStratTags`` are removed and
    ``newStratTags`` are added, while unrelated tags already on the order are
    preserved. Set ``clearTags=True`` to strip every tag from the order; in that
    case ``oldStratTags`` / ``newStratTags`` are ignored and should be omitted.

    Attributes:
        orderId (int): Intent order ID to mutate.
        oldStratTags (Optional[List[str]]): Tags to remove from the order.
        newStratTags (Optional[List[str]]): Tags to add to the order.
        clearTags (Optional[bool]): If True, remove ALL tags from the order.
    """
    orderId: int
