class StratOrdersMessage(BaseModel):
    """
    Response for GET /sentinel/strategy-portfolio/orders.

    Wraps ``ordersByTag`` — one :class:`StratOrdersByTagEntry` per requested tag,
    each holding that tag's intent orders grouped by status. The array order is
    NOT deterministic (the server builds it from a Go map), so look tags up by
    name rather than by position.

    Convenience access::

        msg = portfolio.strategy_orders(["nifty.scalp", "bank.swing"])
        "nifty.scalp" in msg                    # True / False
        msg["nifty.scalp"]                      # StratOrdersByTagEntry
        msg.get("unknown")                      # None
        msg.orders_for("nifty.scalp")           # flat List[IntentOrderResponse], all buckets
        msg.orders_for("nifty.scalp", "open")   # just the 'open' bucket
    """
    ordersByTag: List[StratOrdersByTagEntry] = Field(default_factory=list)

    @field_validator("ordersByTag", mode="before")
    @classmethod
    def _default_empty(cls, value: Any) -> Any:
        return value or []

    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        ser_json_exclude_none=True,
        ser_dict_exclude_none=True,
    )

    def _by_tag(self) -> Dict[str, "StratOrdersByTagEntry"]:
        return {e.stratTag: e for e in self.ordersByTag}

    def __getitem__(self, tag: str) -> "StratOrdersByTagEntry":
        return self._by_tag()[tag]

    def __contains__(self, tag: str) -> bool:
        return any(e.stratTag == tag for e in self.ordersByTag)

    def __iter__(self):
        return iter(e.stratTag for e in self.ordersByTag)

    def __len__(self) -> int:
        return len(self.ordersByTag)

    def get(self, tag: str, default: Any = None) -> Any:
        return self._by_tag().get(tag, default)

    def keys(self) -> List[str]:
        return [e.stratTag for e in self.ordersByTag]

    def entries(self) -> List["StratOrdersByTagEntry"]:
        return list(self.ordersByTag)

    def orders_for(self, tag: str, status: Optional[str] = None) -> List[IntentOrderResponse]:
        """
        Flattened intent orders for ``tag``. With ``status`` (e.g. ``"open"`` or
        ``"executed"``) return only that bucket; otherwise all buckets
        concatenated. Returns [] when the tag or its orders are absent.
        """
        entry = self._by_tag().get(tag)
        if entry is None or entry.intentOrders is None:
            return []
        buckets = entry.intentOrders.orders or {}
        if status is not None:
            return list(buckets.get(status, []) or [])
        out: List[IntentOrderResponse] = []
        for bucket in buckets.values():
            out.extend(bucket or [])
        return out


